export const MAINTENANCE_STANDARD='# PokéBonk Pilot 维护与验收操作指南\n\n本文件由 scripts/sync-maintenance-standard.mjs 从 src/maintenance-prompts.mjs 生成；请修改唯一源后重新生成。以下是现行规则，历史批次不作为本次授权或验收。\n\n'+MAINTENANCE_SECTIONS.map((s,i)=>`## ${i+1}. ${s.title}\n\n${s.body}`).join('\n\n')+'\n';
export const maintenanceTasks={
 full:{name:'适配游戏更新',purpose:'核对官方实际资源与接口变化，修复不兼容，保留全部已有功能和作者使用约束。',focus:'只实施本次官方变化必需的兼容修复，不修改角色路线、单实例或固定等待。'},
 fix:{name:'修复致命故障',purpose:'定位崩溃、无法接入、无法运行等致命缺陷，保留真实失败与验证证据。',focus:'区分故障修复与功能变更，保持既有行为，不能借修复解除单实例或固定等待。'},
};
function maintenanceContext(c){
 const version=v=>typeof v==='string'&&/^\d+(?:\.\d+){1,3}(?:[-+][a-zA-Z0-9.-]{1,32})?$/.test(v)?v:'未知',counts={};
 for(const k of ['pokemon','characters','moves','fusionMoves','items','vitamins','abilities','passives','maps','modes','shiny','lab','quests','guides','builds','targets'])if(Number.isSafeInteger(c.catalogCounts?.[k])&&c.catalogCounts[k]>=0&&c.catalogCounts[k]<=1e8)counts[k]=c.catalogCounts[k];
 return{clientVersion:version(c.clientVersion),gameVersion:version(c.gameVersion),gameHash:typeof c.gameHash==='string'&&/^[a-f0-9]{64}$/i.test(c.gameHash)?c.gameHash.toLowerCase():null,
 checkedAt:typeof c.checkedAt==='string'&&/^\d{4}-\d\d-\d\dT[0-9:.+-]+Z?$/.test(c.checkedAt)&&c.checkedAt.length<=40&&Number.isFinite(Date.parse(c.checkedAt))?c.checkedAt:null,
 compatibilityLevel:['compatible','degraded','unsupported','unknown','full','partial','blocked','supported'].includes(c.compatibilityLevel)?c.compatibilityLevel:'unknown',missingCount:Array.isArray(c.missing)?Math.min(c.missing.length,10000):0,warningCount:Array.isArray(c.warnings)?Math.min(c.warnings.length,10000):0,catalogCounts:counts,sourcePackage:null};
}
